COMMENT ON COLUMN MBW_REFRESH_TOKEN.login_domain IS '로그인 도메인';
COMMENT ON COLUMN MBW_REFRESH_TOKEN.refresh_token_hash IS 'refresh token hash';
COMMENT ON COLUMN MBW_REFRESH_TOKEN.transaction_id IS '발급 전역 transactionId';
COMMENT ON COLUMN MBW_REFRESH_TOKEN.login_operation_id IS '로그인 멱등 Operation ID';
COMMENT ON COLUMN MBW_REFRESH_TOKEN.expire_at IS '만료 일시';
COMMENT ON COLUMN MBW_REFRESH_TOKEN.revoked_yn IS '폐기 여부';
COMMENT ON COLUMN MBW_REFRESH_TOKEN.revoked_at IS '폐기 일시';
COMMENT ON COLUMN MBW_REFRESH_TOKEN.created_by IS '등록자';
COMMENT ON COLUMN MBW_REFRESH_TOKEN.created_at IS '등록일시';
COMMENT ON COLUMN MBW_REFRESH_TOKEN.updated_by IS '수정자';
COMMENT ON COLUMN MBW_REFRESH_TOKEN.updated_at IS '수정일시';
CREATE INDEX ix_mbw_refresh_token_user ON MBW_REFRESH_TOKEN (admin_user_id, revoked_yn, expire_at);
CREATE INDEX ix_mbw_refresh_token_login_operation ON MBW_REFRESH_TOKEN (login_operation_id, revoked_yn);

CREATE TABLE MBW_APPROVAL_DOCUMENT (
    approval_id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    approval_no VARCHAR2(50 CHAR) NOT NULL,
    approval_type VARCHAR2(50 CHAR) NOT NULL,
    business_domain VARCHAR2(30 CHAR) NOT NULL,
    policy_code VARCHAR2(80 CHAR) NULL,
    policy_version NUMBER(10) NULL,
    policy_snapshot_json CLOB NULL,
    title VARCHAR2(200 CHAR) NOT NULL,
    requester_employee_no VARCHAR2(50 CHAR) NOT NULL,
    requester_organization_code VARCHAR2(50 CHAR) NULL,
    requester_position_code VARCHAR2(50 CHAR) NULL,
    requester_job_title_code VARCHAR2(50 CHAR) NULL,
    approval_status VARCHAR2(30 CHAR) DEFAULT 'DRAFT' NOT NULL,
    approval_mode VARCHAR2(30 CHAR) DEFAULT 'SEQUENTIAL' NOT NULL,
    current_step_no NUMBER(10) DEFAULT 0 NOT NULL,
    due_at TIMESTAMP NULL,
    payload_json CLOB NULL,
    payload_hash CHAR(64 CHAR) NULL,
    request_idempotency_key VARCHAR2(120 CHAR) NULL,
    attachment_group_id VARCHAR2(100 CHAR) NULL,
    resubmitted_from_approval_id NUMBER(19) NULL,
    version_no NUMBER(19) DEFAULT 0 NOT NULL,
    transaction_id CHAR(34 CHAR) NULL,
    submitted_at TIMESTAMP(3) NULL,
    completed_at TIMESTAMP(3) NULL,
    created_by VARCHAR2(100 CHAR) DEFAULT 'SYSTEM' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR2(100 CHAR) DEFAULT 'SYSTEM' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT PK_MBW_APPROVAL_DOCUMENT PRIMARY KEY (approval_id),
    CONSTRAINT uk_mbw_approval_document_no UNIQUE (approval_no),
    CONSTRAINT uk_mbw_approval_document_idempotency UNIQUE (request_idempotency_key),
    CONSTRAINT ck_mbw_approval_document_policy_pair CHECK ((policy_code IS NULL AND policy_version IS NULL) OR (policy_code IS NOT NULL AND policy_version IS NOT NULL)),
    CONSTRAINT ck_mbw_approval_document_status CHECK (approval_status IN ('DRAFT','IN_REVIEW','APPROVED','REJECTED','WITHDRAWN','CANCELED','EXPIRED')),
    CONSTRAINT ck_mbw_approval_document_mode CHECK (approval_mode IN ('SEQUENTIAL','PARALLEL')),
    CONSTRAINT ck_mbw_approval_document_step CHECK (current_step_no >= 0),
    CONSTRAINT ck_mbw_approval_document_version CHECK (version_no >= 0),
    CONSTRAINT fk_mbw_approval_document_policy FOREIGN KEY (policy_code, policy_version) REFERENCES MBW_APPROVAL_POLICY (policy_code, policy_version),
    CONSTRAINT fk_mbw_approval_document_resubmit FOREIGN KEY (resubmitted_from_approval_id) REFERENCES MBW_APPROVAL_DOCUMENT (approval_id)
);
COMMENT ON TABLE MBW_APPROVAL_DOCUMENT IS 'Backoffice 결재 문서';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.approval_id IS '결재 문서 순번';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.approval_no IS '결재 문서 번호';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.approval_type IS '결재 유형';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.business_domain IS '요청 업무 영역';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.policy_code IS '적용 결재 정책 코드';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.policy_version IS '적용 결재 정책 버전 Snapshot';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.policy_snapshot_json IS '상신 시 결재 정책/경로 불변 Snapshot JSON';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.title IS '결재 제목';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.requester_employee_no IS '요청자 직원 번호';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.requester_organization_code IS '상신 시 요청자 조직 Snapshot';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.requester_position_code IS '상신 시 요청자 직급 Snapshot';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.requester_job_title_code IS '상신 시 요청자 직책 Snapshot';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.approval_status IS '결재 상태';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.approval_mode IS '결재 방식';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.current_step_no IS '현재 결재 단계';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.due_at IS '결재 기한';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.payload_json IS '결재 업무 데이터 JSON';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.payload_hash IS '결재 대상 Command/Payload SHA-256';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.request_idempotency_key IS '상신 중복 방지 Key';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.attachment_group_id IS '첨부파일 그룹 ID';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.resubmitted_from_approval_id IS '재상신 원본 결재 ID; 원본 Snapshot은 변경하지 않음';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.version_no IS '낙관적 잠금 버전';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.transaction_id IS 'CPF transactionId';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.submitted_at IS '상신 시각';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.completed_at IS '최종 승인/반려/취소 완료 시각';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.created_by IS '등록자';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.created_at IS '등록일시';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.updated_by IS '수정자';
COMMENT ON COLUMN MBW_APPROVAL_DOCUMENT.updated_at IS '수정일시';
CREATE INDEX ix_mbw_approval_document_status ON MBW_APPROVAL_DOCUMENT (approval_status, due_at);
CREATE INDEX ix_mbw_approval_document_requester ON MBW_APPROVAL_DOCUMENT (requester_employee_no, created_at);
CREATE INDEX ix_mbw_approval_document_transaction ON MBW_APPROVAL_DOCUMENT (transaction_id, created_at);
CREATE INDEX ix_mbw_approval_document_resubmit ON MBW_APPROVAL_DOCUMENT (resubmitted_from_approval_id);

CREATE TABLE MBW_APPROVAL_POLICY_STEP (
    policy_code VARCHAR2(80 CHAR) NOT NULL,
    policy_version NUMBER(10) NOT NULL,
    step_no NUMBER(10) NOT NULL,
    step_type VARCHAR2(30 CHAR) DEFAULT 'APPROVAL' NOT NULL,
    target_type VARCHAR2(30 CHAR) NOT NULL,
    target_code VARCHAR2(100 CHAR) NOT NULL,
    decision_rule VARCHAR2(20 CHAR) DEFAULT 'ALL' NOT NULL,
    required_count NUMBER(10) NULL,
    required_yn CHAR(1 CHAR) DEFAULT 'Y' NOT NULL,
    sort_order NUMBER(10) DEFAULT 0 NOT NULL,
    created_by VARCHAR2(100 CHAR) DEFAULT 'SYSTEM' NOT NULL,
    created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) NOT NULL,
    updated_by VARCHAR2(100 CHAR) DEFAULT 'SYSTEM' NOT NULL,
    updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) NOT NULL,
    CONSTRAINT PK_MBW_APPROVAL_POLICY_STEP PRIMARY KEY (policy_code, policy_version, step_no, target_type, target_code),
    CONSTRAINT ck_mbw_approval_policy_step_no CHECK (step_no >= 1),
    CONSTRAINT ck_mbw_approval_policy_step_type CHECK (step_type IN ('APPROVAL','AGREEMENT','REVIEW')),
    CONSTRAINT ck_mbw_approval_policy_step_target CHECK (target_type IN ('EMPLOYEE','ROLE','ORGANIZATION','ORG_MANAGER','POSITION')),
    CONSTRAINT ck_mbw_approval_policy_step_rule CHECK (decision_rule IN ('ALL','ANY','N_OF_M')),
    CONSTRAINT ck_mbw_approval_policy_step_required CHECK (required_yn IN ('Y','N') AND ( (decision_rule = 'N_OF_M' AND required_count IS NOT NULL AND required_count > 0) OR (decision_rule <> 'N_OF_M' AND required_count IS NULL) )),
    CONSTRAINT fk_mbw_approval_policy_step_policy FOREIGN KEY (policy_code, policy_version) REFERENCES MBW_APPROVAL_POLICY (policy_code, policy_version) ON DELETE CASCADE
);
COMMENT ON TABLE MBW_APPROVAL_POLICY_STEP IS 'Backoffice 업무 결재 정책 단계';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.policy_code IS '업무 결재 정책 코드';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.policy_version IS '정책 버전';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.step_no IS '결재 단계';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.step_type IS 'APPROVAL/AGREEMENT/REVIEW';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.target_type IS 'EMPLOYEE/ROLE/ORGANIZATION/ORG_MANAGER/POSITION';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.target_code IS '대상 코드';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.decision_rule IS 'ALL/ANY/N_OF_M';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.required_count IS 'N_OF_M 최소 결정 수';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.required_yn IS '필수 대상 여부';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.sort_order IS '동일 단계 표시 순서';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.created_by IS '등록자';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.created_at IS '등록일시';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.updated_by IS '수정자';
COMMENT ON COLUMN MBW_APPROVAL_POLICY_STEP.updated_at IS '수정일시';

CREATE TABLE MBW_EMPLOYEE (
    employee_id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_no VARCHAR2(50 CHAR) NOT NULL,
    admin_user_id NUMBER(19) NULL,
    organization_code VARCHAR2(50 CHAR) NOT NULL,
    employee_name VARCHAR2(100 CHAR) NOT NULL,
    position_code VARCHAR2(50 CHAR) NULL,
    job_title_code VARCHAR2(50 CHAR) NULL,
    manager_employee_no VARCHAR2(50 CHAR) NULL,
    employment_status VARCHAR2(30 CHAR) DEFAULT 'EMPLOYED' NOT NULL,
    join_date DATE NULL,
    leave_date DATE NULL,
    email VARCHAR2(200 CHAR) NULL,
    mobile_no VARCHAR2(50 CHAR) NULL,
    office_phone_no VARCHAR2(50 CHAR) NULL,
    use_yn CHAR(1 CHAR) DEFAULT 'Y' NOT NULL,
    version_no NUMBER(19) DEFAULT 0 NOT NULL,
    created_by VARCHAR2(100 CHAR) DEFAULT 'SYSTEM' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR2(100 CHAR) DEFAULT 'SYSTEM' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT PK_MBW_EMPLOYEE PRIMARY KEY (employee_id),
    CONSTRAINT uk_mbw_employee_no UNIQUE (employee_no),
    CONSTRAINT uk_mbw_employee_admin_user UNIQUE (admin_user_id),
    CONSTRAINT ck_mbw_employee_use CHECK (use_yn IN ('Y','N')),
    CONSTRAINT ck_mbw_employee_status CHECK (employment_status IN ('EMPLOYED','ON_LEAVE','SECONDMENT','DISPATCHED','RETIRED','TERMINATED')),
    CONSTRAINT ck_mbw_employee_employment_period CHECK (leave_date IS NULL OR join_date IS NULL OR leave_date >= join_date),
    CONSTRAINT fk_mbw_employee_admin_user FOREIGN KEY (admin_user_id) REFERENCES MBW_ADMIN_USER (admin_user_id) ON DELETE SET NULL,
    CONSTRAINT fk_mbw_employee_organization FOREIGN KEY (organization_code) REFERENCES MBW_ORGANIZATION (organization_code),
    CONSTRAINT fk_mbw_employee_position FOREIGN KEY (position_code) REFERENCES MBW_POSITION (position_code) ON DELETE SET NULL,
    CONSTRAINT fk_mbw_employee_job_title FOREIGN KEY (job_title_code) REFERENCES MBW_JOB_TITLE (job_title_code) ON DELETE SET NULL
);
COMMENT ON TABLE MBW_EMPLOYEE IS 'Backoffice 직원 프로필';
COMMENT ON COLUMN MBW_EMPLOYEE.employee_id IS '직원 순번';
COMMENT ON COLUMN MBW_EMPLOYEE.employee_no IS '직원 번호';
COMMENT ON COLUMN MBW_EMPLOYEE.admin_user_id IS '연결 업무 관리자 사용자 순번';
COMMENT ON COLUMN MBW_EMPLOYEE.organization_code IS '대표 조직 코드; 유효 소속 정본은 MBW_EMPLOYEE_ASSIGNMENT';
COMMENT ON COLUMN MBW_EMPLOYEE.employee_name IS '직원명';
COMMENT ON COLUMN MBW_EMPLOYEE.position_code IS '직급 코드';
COMMENT ON COLUMN MBW_EMPLOYEE.job_title_code IS '직책 코드';
COMMENT ON COLUMN MBW_EMPLOYEE.manager_employee_no IS '상위 관리자 직원 번호';
COMMENT ON COLUMN MBW_EMPLOYEE.employment_status IS '재직 상태; 신규 직원 기본값 EMPLOYED';
COMMENT ON COLUMN MBW_EMPLOYEE.join_date IS '입사일';
COMMENT ON COLUMN MBW_EMPLOYEE.leave_date IS '퇴사일';
COMMENT ON COLUMN MBW_EMPLOYEE.email IS '업무 이메일';
COMMENT ON COLUMN MBW_EMPLOYEE.mobile_no IS '연락처(휴대폰); 숫자형이 아닌 문자열로 국가번호와 선행 0을 보존';
COMMENT ON COLUMN MBW_EMPLOYEE.office_phone_no IS '내부 전화번호/내선; 휴대폰 연락처와 분리';
COMMENT ON COLUMN MBW_EMPLOYEE.use_yn IS '사용 여부';
COMMENT ON COLUMN MBW_EMPLOYEE.version_no IS '낙관적 잠금 버전';
COMMENT ON COLUMN MBW_EMPLOYEE.created_by IS '등록자';
COMMENT ON COLUMN MBW_EMPLOYEE.created_at IS '등록일시';
COMMENT ON COLUMN MBW_EMPLOYEE.updated_by IS '수정자';
COMMENT ON COLUMN MBW_EMPLOYEE.updated_at IS '수정일시';
CREATE INDEX ix_mbw_employee_organization ON MBW_EMPLOYEE (organization_code, employment_status);

CREATE TABLE MBW_USER_ROLE (
    user_role_id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
