CREATE TABLE MBW_APPROVAL_LINE (
    approval_line_id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    approval_id NUMBER(19) NOT NULL,
    step_no NUMBER(10) NOT NULL,
    approver_employee_no VARCHAR2(50 CHAR) NULL,
    step_type VARCHAR2(30 CHAR) DEFAULT 'APPROVAL' NOT NULL,
    target_type VARCHAR2(30 CHAR) DEFAULT 'EMPLOYEE' NOT NULL,
    target_code VARCHAR2(100 CHAR) NOT NULL,
    target_name_snapshot VARCHAR2(150 CHAR) NULL,
    decision_rule VARCHAR2(30 CHAR) DEFAULT 'ALL' NOT NULL,
    required_count NUMBER(10) NULL,
    required_yn CHAR(1 CHAR) DEFAULT 'Y' NOT NULL,
    decision_status VARCHAR2(30 CHAR) DEFAULT 'WAITING' NOT NULL,
    decision_comment VARCHAR2(1000 CHAR) NULL,
    decided_at TIMESTAMP NULL,
    created_by VARCHAR2(100 CHAR) DEFAULT 'SYSTEM' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by VARCHAR2(100 CHAR) DEFAULT 'SYSTEM' NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT PK_MBW_APPROVAL_LINE PRIMARY KEY (approval_line_id),
    CONSTRAINT uk_mbw_approval_line UNIQUE (approval_id, step_no, target_type, target_code),
    CONSTRAINT ck_mbw_approval_line_step CHECK (step_no >= 1),
    CONSTRAINT ck_mbw_approval_line_step_type CHECK (step_type IN ('APPROVAL','AGREEMENT','REVIEW')),
    CONSTRAINT ck_mbw_approval_line_target CHECK (target_type IN ('EMPLOYEE','ROLE','ORGANIZATION','ORG_MANAGER','POSITION')),
    CONSTRAINT ck_mbw_approval_line_rule CHECK (decision_rule IN ('ALL','ANY','N_OF_M')),
    CONSTRAINT ck_mbw_approval_line_required CHECK (required_yn IN ('Y','N') AND ( (decision_rule = 'N_OF_M' AND required_count IS NOT NULL AND required_count > 0) OR (decision_rule <> 'N_OF_M' AND required_count IS NULL) )),
    CONSTRAINT ck_mbw_approval_line_status CHECK (decision_status IN ('WAITING','APPROVED','AGREED','REJECTED','SKIPPED')),
    CONSTRAINT fk_mbw_approval_line_document FOREIGN KEY (approval_id) REFERENCES MBW_APPROVAL_DOCUMENT (approval_id) ON DELETE CASCADE
);
COMMENT ON TABLE MBW_APPROVAL_LINE IS 'Backoffice 결재선';
COMMENT ON COLUMN MBW_APPROVAL_LINE.approval_line_id IS '결재선 순번';
COMMENT ON COLUMN MBW_APPROVAL_LINE.approval_id IS '결재 문서 순번';
COMMENT ON COLUMN MBW_APPROVAL_LINE.step_no IS '결재 단계';
COMMENT ON COLUMN MBW_APPROVAL_LINE.approver_employee_no IS '직접 직원 대상 호환 필드; 정책 기반 결재는 participant Snapshot 사용';
COMMENT ON COLUMN MBW_APPROVAL_LINE.step_type IS 'APPROVAL/AGREEMENT/REVIEW';
COMMENT ON COLUMN MBW_APPROVAL_LINE.target_type IS 'EMPLOYEE/ROLE/ORGANIZATION/ORG_MANAGER/POSITION';
COMMENT ON COLUMN MBW_APPROVAL_LINE.target_code IS '정책 Target 코드 Snapshot; EMPLOYEE이면 직원번호';
COMMENT ON COLUMN MBW_APPROVAL_LINE.target_name_snapshot IS '정책 Target 표시명 Snapshot';
COMMENT ON COLUMN MBW_APPROVAL_LINE.decision_rule IS 'ALL/ANY/N_OF_M';
COMMENT ON COLUMN MBW_APPROVAL_LINE.required_count IS 'N_OF_M 최소 결정 수';
COMMENT ON COLUMN MBW_APPROVAL_LINE.required_yn IS '필수 Target 여부';
COMMENT ON COLUMN MBW_APPROVAL_LINE.decision_status IS '결재자 결정 상태';
COMMENT ON COLUMN MBW_APPROVAL_LINE.decision_comment IS '결재 의견';
COMMENT ON COLUMN MBW_APPROVAL_LINE.decided_at IS '결정 일시';
COMMENT ON COLUMN MBW_APPROVAL_LINE.created_by IS '등록자';
COMMENT ON COLUMN MBW_APPROVAL_LINE.created_at IS '등록일시';
COMMENT ON COLUMN MBW_APPROVAL_LINE.updated_by IS '수정자';
COMMENT ON COLUMN MBW_APPROVAL_LINE.updated_at IS '수정일시';
CREATE INDEX ix_mbw_approval_line_approver ON MBW_APPROVAL_LINE (approver_employee_no, decision_status);

CREATE TABLE MBW_APPROVAL_DELEGATION (
    delegation_id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    delegator_employee_no VARCHAR2(50 CHAR) NOT NULL,
    delegate_employee_no VARCHAR2(50 CHAR) NOT NULL,
    business_domain VARCHAR2(30 CHAR) NULL,
    approval_type VARCHAR2(50 CHAR) NULL,
    valid_from TIMESTAMP(3) NOT NULL,
    valid_to TIMESTAMP(3) NOT NULL,
    reason VARCHAR2(500 CHAR) NOT NULL,
    use_yn CHAR(1 CHAR) DEFAULT 'Y' NOT NULL,
    created_by VARCHAR2(100 CHAR) DEFAULT 'SYSTEM' NOT NULL,
    created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) NOT NULL,
    updated_by VARCHAR2(100 CHAR) DEFAULT 'SYSTEM' NOT NULL,
    updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) NOT NULL,
    CONSTRAINT PK_MBW_APPROVAL_DELEGATION PRIMARY KEY (delegation_id),
    CONSTRAINT ck_mbw_approval_delegation_use CHECK (use_yn IN ('Y','N')),
    CONSTRAINT ck_mbw_approval_delegation_period CHECK (valid_to > valid_from),
    CONSTRAINT ck_mbw_approval_delegation_self CHECK (delegator_employee_no <> delegate_employee_no),
    CONSTRAINT fk_mbw_approval_delegation_from FOREIGN KEY (delegator_employee_no) REFERENCES MBW_EMPLOYEE (employee_no),
    CONSTRAINT fk_mbw_approval_delegation_to FOREIGN KEY (delegate_employee_no) REFERENCES MBW_EMPLOYEE (employee_no)
);
COMMENT ON TABLE MBW_APPROVAL_DELEGATION IS 'Backoffice 결재 위임/대결 유효기간';
