CREATE TABLE MBW_APPROVAL_PARTICIPANT (
    approval_participant_id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    approval_id NUMBER(19) NOT NULL,
    approval_line_id NUMBER(19) NOT NULL,
    step_no NUMBER(10) NOT NULL,
    approver_employee_no VARCHAR2(50 CHAR) NOT NULL,
    approver_name_snapshot VARCHAR2(100 CHAR) NULL,
    organization_code_snapshot VARCHAR2(50 CHAR) NULL,
    position_code_snapshot VARCHAR2(50 CHAR) NULL,
    job_title_code_snapshot VARCHAR2(50 CHAR) NULL,
    delegated_from_employee_no VARCHAR2(50 CHAR) NULL,
    resolution_source VARCHAR2(30 CHAR) DEFAULT 'DIRECT' NOT NULL,
    decision_status VARCHAR2(30 CHAR) DEFAULT 'WAITING' NOT NULL,
    idempotency_key VARCHAR2(120 CHAR) NULL,
    decision_comment VARCHAR2(1000 CHAR) NULL,
    decided_at TIMESTAMP(3) NULL,
    created_by VARCHAR2(100 CHAR) DEFAULT 'SYSTEM' NOT NULL,
    created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) NOT NULL,
    updated_by VARCHAR2(100 CHAR) DEFAULT 'SYSTEM' NOT NULL,
    updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) NOT NULL,
    CONSTRAINT PK_MBW_APPROVAL_PARTICIPANT PRIMARY KEY (approval_participant_id),
    CONSTRAINT uk_mbw_approval_participant UNIQUE (approval_line_id, approver_employee_no),
    CONSTRAINT uk_mbw_approval_participant_idem UNIQUE (idempotency_key),
    CONSTRAINT ck_mbw_approval_participant_step CHECK (step_no >= 1),
    CONSTRAINT ck_mbw_approval_participant_source CHECK (resolution_source IN ('DIRECT','ROLE','ORG','ORG_MANAGER','POSITION','DELEGATION','ACTING')),
    CONSTRAINT ck_mbw_approval_participant_status CHECK (decision_status IN ('WAITING','APPROVED','AGREED','REJECTED','SKIPPED')),
    CONSTRAINT fk_mbw_approval_participant_document FOREIGN KEY (approval_id) REFERENCES MBW_APPROVAL_DOCUMENT (approval_id) ON DELETE CASCADE,
    CONSTRAINT fk_mbw_approval_participant_line FOREIGN KEY (approval_line_id) REFERENCES MBW_APPROVAL_LINE (approval_line_id) ON DELETE CASCADE
);
COMMENT ON TABLE MBW_APPROVAL_PARTICIPANT IS 'Backoffice 결재 참여자 Snapshot';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.approval_participant_id IS '실제 결재 참여자 순번';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.approval_id IS '결재 문서 순번';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.approval_line_id IS '정책 Target/결재선 순번';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.step_no IS '결재 단계';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.approver_employee_no IS '상신 시 해석된 실제 결재자';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.approver_name_snapshot IS '상신 시 결재자 표시명 Snapshot';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.organization_code_snapshot IS '결재자 조직 Snapshot';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.position_code_snapshot IS '결재자 직급 Snapshot';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.job_title_code_snapshot IS '결재자 직책 Snapshot';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.delegated_from_employee_no IS '위임 원 결재자';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.resolution_source IS 'DIRECT/ROLE/ORG/ORG_MANAGER/POSITION/DELEGATION/ACTING';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.decision_status IS 'WAITING/APPROVED/AGREED/REJECTED/SKIPPED';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.idempotency_key IS '결정 멱등 키';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.decision_comment IS '결재 의견';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.decided_at IS '결정 시각';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.created_by IS '등록자';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.created_at IS '등록일시';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.updated_by IS '수정자';
COMMENT ON COLUMN MBW_APPROVAL_PARTICIPANT.updated_at IS '수정일시';
CREATE INDEX ix_mbw_approval_participant_inbox ON MBW_APPROVAL_PARTICIPANT (approver_employee_no, decision_status, approval_id);

